var findRotation = function(mat, target) {
    const n = mat.length;
    const rotate = (m) => {
        const next = Array.from({ length: n }, () => Array(n));
        for (let r = 0; r < n; ++r) {
            for (let c = 0; c < n; ++c) {
                next[c][n - 1 - r] = m[r][c];
            }
        }
        return next;
    };

    const equals = (a, b) => {
        for (let i = 0; i < n; ++i) {
            for (let j = 0; j < n; ++j) {
                if (a[i][j] !== b[i][j]) return false;
            }
        }
        return true;
    };

    let curr = mat;
    for (let k = 0; k < 4; ++k) {
        if (equals(curr, target)) return true;
        curr = rotate(curr);
    }
    return false;
};
